import{_ as r,C as i,o as d,c,a6 as h,E as o,w as n,j as e,a as t}from"./chunks/framework.CWrlzS1v.js";const b=JSON.parse('{"title":"Switch from Sandbox to Live Mode","description":"Sandbox mode is for tests and TaxJar does not record its transactions. Change to Live mode, connect each company with its Live token, and check the result.","frontmatter":{"title":"Switch from Sandbox to Live Mode","description":"Sandbox mode is for tests and TaxJar does not record its transactions. Change to Live mode, connect each company with its Live token, and check the result.","type":"how-to"},"headers":[],"relativePath":"setting-up/before-you-go-live.md","filePath":"setting-up/before-you-go-live.md"}'),u={name:"setting-up/before-you-go-live.md"};function p(g,a,m,f,v,x){const s=i("PluginTabsTab"),l=i("PluginTabs");return d(),c("div",null,[a[2]||(a[2]=h('<h1 id="before-you-go-live" tabindex="-1">Before you go live <a class="header-anchor" href="#before-you-go-live" aria-label="Permalink to &quot;Before you go live&quot;">​</a></h1><p>The app has two API modes. Use Sandbox mode to test the setup, and Live mode to run your business.</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Sandbox Mode</th><th style="text-align:center;">Live Mode</th></tr></thead><tbody><tr><td>Current tax rates</td><td style="text-align:center;"></td><td style="text-align:center;">●</td></tr><tr><td>TaxJar records the transactions for reports and AutoFile</td><td style="text-align:center;"></td><td style="text-align:center;">●</td></tr><tr><td>API calls are free of your TaxJar plan quota</td><td style="text-align:center;">●</td><td style="text-align:center;"></td></tr></tbody></table><p>The mode applies to all companies on the site. Each company has one Sandbox token and one Live token.</p><h2 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h2><ul><li>Copy the <strong>Live</strong> API token of each company from <a href="https://app.taxjar.com/account#api-access" target="_blank" rel="noreferrer">TaxJar → Account → API Access</a>.</li><li>You need to be a TaxJar Manager. Refer to <a href="/usa/sales-tax/pr-preview/pr-34/setting-up/roles-and-permissions">Roles &amp; Permissions</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Change the mode before you submit real invoices</p><p>An invoice that you submit in Sandbox mode goes to the TaxJar sandbox. It shows <strong>Synced</strong>, but it is not in your Live TaxJar account, and AutoFile does not file it.</p></div><h2 id="go-live" tabindex="-1">Go Live <a class="header-anchor" href="#go-live" aria-label="Permalink to &quot;Go Live&quot;">​</a></h2><ol class="steps"><li><details><summary><h3 id="change-the-mode">Change the mode</h3><span>Switch to Live, and connect each company with its Live token.</span></summary><ol><li>Open <strong>TaxJar Setup</strong> and click <strong>Edit configuration</strong>.</li><li>On the <strong>Connect</strong> step, in <strong>API Mode</strong>, click <strong>Live</strong>.</li><li>For each company, paste the Live token into <strong>Live token</strong>, then click <strong>Connect</strong>. Wait for the green <strong>Connected</strong> status.</li><li>Click <strong>Save &amp; continue</strong> on each step, then click <strong>Activate</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">What the app does after you save</p><ul><li>It gets the nexus states again for each company.</li><li>In Live mode, it sends to TaxJar each exempt customer that is not in TaxJar yet.</li><li>If the site upgraded from TaxJar version 15, it starts the check of the older invoices. Refer to <a href="/usa/sales-tax/pr-preview/pr-34/reference/upgrade-from-version-15">Upgrade from Version 15</a>.</li></ul></div></details></li><li><details><summary><h3 id="check-the-result">Check the result</h3><span>Make sure that the setup is in Live mode, and test one invoice.</span></summary><ol><li>Open <strong>TaxJar Setup</strong>. The <strong>Connection</strong> card shows <strong>API Mode</strong> as <strong>Live</strong>.</li><li>Save a test sales invoice for a customer in a nexus state. Check that it has a <strong>Sales Tax</strong> row. Then delete the invoice.</li></ol></details></li></ol><h2 id="missing-live-token" tabindex="-1">Missing Live Token <a class="header-anchor" href="#missing-live-token" aria-label="Permalink to &quot;Missing Live Token&quot;">​</a></h2><p>A company that has no token for the current mode gets no tax, and its invoices do not sync. The sync error is:</p><blockquote><p>{company} has no Live API token, and TaxJar is in Live mode. Enter one in the guided setup.</p></blockquote><ol><li>Add the Live token of the company on the <strong>Connect</strong> step of TaxJar Setup.</li><li>The app sends the failed invoices again within 15 minutes. To send them at once, refer to <a href="/usa/sales-tax/pr-preview/pr-34/transaction-sync/resolve-failed-syncs">Resolve Failed Syncs</a>.</li></ol><h2 id="turn-off-the-app" tabindex="-1">Turn Off the App <a class="header-anchor" href="#turn-off-the-app" aria-label="Permalink to &quot;Turn Off the App&quot;">​</a></h2><p>There are two ways to stop TaxJar for all companies.</p>',15)),o(l,null,{default:n(()=>[o(s,{label:"Clear Enable TaxJar"},{default:n(()=>[...a[0]||(a[0]=[e("ol",null,[e("li",null,[t("Open "),e("strong",null,"TaxJar API Settings"),t(".")]),e("li",null,[t("Clear "),e("strong",null,"Enable TaxJar"),t(", and save.")])],-1),e("p",null,"Then:",-1),e("ul",null,[e("li",null,"The app calculates no tax and sends no transactions."),e("li",null,"It hides its parts on the forms."),e("li",null,[t("Invoices that you submit get the status "),e("strong",null,"Excluded"),t(".")]),e("li",null,"The TaxJar Sales Tax template is no longer the default template."),e("li",null,'The standard templates "US ST 6%", "US ST 4%" and "US ST 6.25%" stay disabled.')],-1)])]),_:1}),o(s,{label:"Disable the App"},{default:n(()=>[...a[1]||(a[1]=[e("p",null,"When you disable the TaxJar Integration app on the site:",-1),e("ul",null,[e("li",null,"The app hides its fields. It does not delete your data."),e("li",null,"The TaxJar Sales Tax template is no longer the default template."),e("li",null,'The app enables "US ST 6%", "US ST 4%" and "US ST 6.25%" again.'),e("li",null,"The scheduled jobs stop.")],-1),e("div",{class:"warning custom-block"},[e("p",{class:"custom-block-title"},"Select a default tax template"),e("p",null,[t("After you disable the app, no sales tax template is the default. Select a default "),e("strong",null,"Sales Taxes and Charges Template"),t(" for each company.")])],-1),e("p",null,"When you enable the app again, the fields and the default template come back.",-1)])]),_:1})]),_:1})])}const y=r(u,[["render",p]]);export{b as __pageData,y as default};
